    "explanation": "Luật Đấu thầu cho phép áp dụng chỉ định thầu hoặc phụ lục bổ sung đối với khối lượng phát sinh hợp lý không quá 20%.",
    "legalBasis": "Điều 23, Điều 70 Luật Đấu thầu 22/2023/QH15",
    "difficulty": "Nâng cao",
